-- Existing synthetic actor/source and rollback-only native findings; no providers/users.
begin;set local statement_timeout='90s';select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999902',true);
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end $$;
create function pg_temp.expect_error(query text,code text,label text) returns void language plpgsql as $$begin begin execute query;exception when others then if sqlstate=code then raise notice 'PASS %',label;return;end if;raise exception 'FAIL % expected % got %: %',label,code,sqlstate,sqlerrm;end;raise exception 'FAIL % did not reject',label;end $$;
do $$declare org uuid:='99999999-9999-4999-8999-999999999901';project uuid:='99999999-9999-4999-8999-999999999974';version uuid:='99999999-9999-4999-8999-999999997141';page1 uuid;page2 uuid;engagement uuid;review jsonb;result jsonb;checked timestamptz;evidence jsonb;first_check uuid;j jsonb;baseline bigint;oversized_findings jsonb;extra_page jsonb;begin
 select id,engagement_id into page1,engagement from public.project_website_pages where organization_id=org and project_id=project and page_key='page:1';if not found then raise exception 'Verified AD1 fixture absent';end if;
 review:=public.preview_project_website_pages(org,project,version,'["page:2"]');result:=public.register_project_website_pages(org,project,version,'["page:2"]',review->>'review_sha256','99999999-9999-4999-8999-999999997300');page2:=(result#>>'{pages,0,page_id}')::uuid;
 j:=public.list_project_website_site_findings(org,project,version);baseline:=(j->>'total')::bigint;
 evidence:=jsonb_build_object('indexed',null,'schema_valid',false,'mobile_score',0,'desktop_score',null,'notes','Scoped rollback site evidence','evidence_url',null,'findings',jsonb_build_array(jsonb_build_object('category','schema','severity','warning','description','SITE_FINDING_ALPHA schema issue','evidence','Manual inspector'),jsonb_build_object('category','content','severity','info','description','SITE_FINDING_ALPHA content issue','evidence','Manual note'),jsonb_build_object('category','performance','severity','warning','description','SITE_FINDING_ALPHA performance issue','evidence','Manual score')));checked:=clock_timestamp();review:=public.preview_project_website_version_check(org,project,page1,version,checked,evidence);result:=public.confirm_project_website_version_check(org,project,page1,version,checked,evidence,review->>'review_sha256','99999999-9999-4999-8999-999999997301');first_check:=(result#>>'{check,id}')::uuid;
 evidence:=evidence||jsonb_build_object('findings',jsonb_build_array(jsonb_build_object('category','schema','severity','critical','description','SITE_FINDING_BETA schema issue','evidence','Manual inspector')));checked:=clock_timestamp();review:=public.preview_project_website_version_check(org,project,page2,version,checked,evidence);perform public.confirm_project_website_version_check(org,project,page2,version,checked,evidence,review->>'review_sha256','99999999-9999-4999-8999-999999997302');
 j:=public.list_project_website_site_findings(org,project,version,'SITE_FINDING',null,null,0,1);
 perform pg_temp.check_true(j->>'projection'='latest_manual_check_per_registered_page' and j->>'matching'='4' and jsonb_array_length(j->'items')=1 and j->>'has_more'='true','Site finding rows are bounded independently from whole/matching totals');
 perform pg_temp.check_true(j#>>'{items,0,page_id}'=page2::text and j#>>'{items,0,finding_number}'='1' and j#>>'{items,0,original_architecture_version_id}'=version::text,'Finding links exact canonical page original check/version and ordinal');
 perform pg_temp.check_true(j->>'provider_request_made'='false' and j->>'provider_verified'='false' and j#>>'{items,0,source_type}'='manual','Manual site findings never imply provider fetch or verification');
 perform pg_temp.check_true(j->>'source_total_pages'='101' and (j->>'registered_pages')::int>=2 and (j->>'pages_with_manual_checks')::int>=2 and (j->>'registered_pages_without_manual_checks')::int=(j->>'registered_pages')::int-(j->>'pages_with_manual_checks')::int,'Source registry and manual-check coverage counters remain separate');
 j:=public.list_project_website_site_findings(org,project,version,'SITE_FINDING','warning','schema');
 perform pg_temp.check_true(j->>'matching'='1' and j#>>'{items,0,finding,description}'='SITE_FINDING_ALPHA schema issue' and (j->>'total')::int>=4,'Category/severity filter keeps exact original finding and independent whole total');
 j:=public.list_project_website_site_findings(org,project,version,'no-matching-scoped-finding');perform pg_temp.check_true(j->>'matching'='0' and j->'items'='[]'::jsonb and (j->>'total')::int>=4,'Empty filtered findings do not fabricate a missing measurement zero');
 j:=public.list_project_website_site_findings(org,project,version,'SITE_FINDING',null,null,1,2);perform pg_temp.check_true(j->>'offset'='1' and jsonb_array_length(j->'items')=2 and j#>>'{items,0,page_id}'=page1::text,'Paging preserves exact linked page/check identities');
 j:=public.list_project_website_site_findings(org,project,'99999999-9999-4999-8999-999999997143','SITE_FINDING');perform pg_temp.check_true(j#>'{items,0,recheck_reasons}' ? 'architecture_version_changed','Different explicit approved version derives recheck without replacing original check');
 perform pg_temp.expect_error(format('select public.list_project_website_site_findings(%L,%L,%L,%L,null,null,0,51)',org,project,version,''),'22023','Unbounded site history rejected');
 perform pg_temp.expect_error(format('select public.list_project_website_site_findings(%L,%L,%L,%L,%L)',org,project,version,'','urgent'),'22023','Unrecognized severity rejected');
 perform pg_temp.expect_error(format('select public.list_project_website_site_findings(%L,%L,%L,%L,null,%L)',org,project,version,'','provider_claim'),'22023','Unrecognized category rejected');
 perform pg_temp.expect_error(format('select public.list_project_website_site_findings(%L,%L,%L,%L)',org,project,version,repeat('a',121)),'22023','Oversized site search rejected');
 perform pg_temp.expect_error(format('select public.list_project_website_site_findings(%L,%L,%L)',org,project,'99999999-9999-4999-8999-999999997299'),'42501','Missing source cannot borrow another project findings');
 perform pg_temp.expect_error(format('select public.list_project_website_site_findings(%L,%L,%L)',org,'99999999-9999-4999-8999-999999997299',version),'42501','Missing project cannot expose original page metadata');
 evidence:=evidence||jsonb_build_object('findings',jsonb_build_array());checked:=clock_timestamp();review:=public.preview_project_website_version_check(org,project,page1,version,checked,evidence);perform public.confirm_project_website_version_check(org,project,page1,version,checked,evidence,review->>'review_sha256','99999999-9999-4999-8999-999999997303');
 j:=public.list_project_website_site_findings(org,project,version,'SITE_FINDING');perform pg_temp.check_true(j->>'matching'='1' and j#>>'{items,0,page_id}'=page2::text,'Newer manual check becomes current site projection without duplicating old findings');
 perform pg_temp.check_true((select jsonb_array_length(c.evidence->'findings')=3 from public.project_website_version_checks c where c.id=first_check),'Previous manual finding evidence remains immutable in page history');
 insert into public.tracked_page_audits(organization_id,tracked_page_id,audit_date,issues,notes,source_type,created_by) values(org,'99999999-9999-4999-8999-999999997150','2000-01-04',array['LEGACY_FINDING_UNBOUND'],'Legacy manual finding remains separately unbound','manual',auth.uid());
 j:=public.list_project_website_site_findings(org,project,version,'LEGACY_FINDING_UNBOUND');perform pg_temp.check_true(j->>'matching'='0','Legacy unbound page findings are never retroactively copied into exact version checks');
 -- Whole response bound across multiple individually valid page checks.
 select jsonb_agg(jsonb_build_object('category','technical','severity','warning','description','OVERSIZE_SITE_'||i||repeat('a',800),'evidence',repeat('b',2000))) into oversized_findings from generate_series(1,10)i;
 review:=public.preview_project_website_pages(org,project,version,'["page:3","page:4","page:5","page:6","page:7"]');result:=public.register_project_website_pages(org,project,version,'["page:3","page:4","page:5","page:6","page:7"]',review->>'review_sha256',gen_random_uuid());
 for extra_page in select value from jsonb_array_elements(result->'pages') loop
 evidence:=evidence||jsonb_build_object('findings',oversized_findings);checked:=clock_timestamp();review:=public.preview_project_website_version_check(org,project,(extra_page->>'page_id')::uuid,version,checked,evidence);perform public.confirm_project_website_version_check(org,project,(extra_page->>'page_id')::uuid,version,checked,evidence,review->>'review_sha256',gen_random_uuid());
 end loop;
 perform pg_temp.expect_error(format('select public.list_project_website_site_findings(%L,%L,%L,%L,null,null,0,50)',org,project,version,'OVERSIZE_SITE_'),'22023','Whole site response rejects oversized valid records without silent truncation');
 update public.engagements set status='on_hold' where id=engagement;
 j:=public.list_project_website_site_findings(org,project,version,'SITE_FINDING');perform pg_temp.check_true(j->>'source_state'='approved_source_unavailable' and j->'source_total_pages'='null'::jsonb and j#>>'{items,0,recheck_required}'='true','Withdrawn source retains page-linked manual history with unknown current planned total');
 update public.engagements set status='active' where id=engagement;
 update public.projects set archived_at=clock_timestamp() where id=project;
 j:=public.list_project_website_site_findings(org,project,version,'SITE_FINDING');perform pg_temp.check_true(j->>'source_state'='archived' and j#>>'{items,0,source_state}'='archived','Archived project exposes retained team history without fresh acceptance');
 update public.projects set archived_at=null where id=project;
 perform set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999997299',true);
 perform pg_temp.expect_error(format('select public.list_project_website_site_findings(%L,%L,%L)',org,project,version),'42501','Unknown actor cannot read site finding projection');
end $$;
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999902',true);
set local role authenticated;
select pg_temp.check_true(public.list_project_website_site_findings('99999999-9999-4999-8999-999999999901','99999999-9999-4999-8999-999999999974','99999999-9999-4999-8999-999999997141','SITE_FINDING')->>'provider_verified'='false','Authenticated current team reads bounded site findings API');
reset role;set local role anon;
select pg_temp.expect_error('select public.list_project_website_site_findings(null,null,null)','42501','Anonymous site API denied');
reset role;set local role service_role;
select pg_temp.expect_error('select public.list_project_website_site_findings(null,null,null)','42501','Service-role site API denied');
reset role;rollback;
